import time
from session_store import SessionStore

def test_session_expiry():
    """Test that sessions expire correctly."""
    def fixed_time():
        return 1000.0

    s = SessionStore(clock=fixed_time)
    s.register("192.168.1.1", 60.0)

    # Advance time to exactly the expiration boundary
    def expired_time():
        return 1060.0  # Exactly at expiration

    s._clock = expired_time
    assert s.is_active("192.168.1.1") is False
